-- Additive contracts for the institutional site; no existing user or operation is changed.
BEGIN;
CREATE TABLE IF NOT EXISTS core.site_categorias(codigo text PRIMARY KEY,nome text NOT NULL,motor text NOT NULL);
CREATE TABLE IF NOT EXISTS core.site_cadastros(
 id uuid PRIMARY KEY,request_id uuid NOT NULL UNIQUE,payload_hash text NOT NULL,
 tipo text NOT NULL CHECK(tipo IN('motorista','negocio')),cidade_id uuid NOT NULL REFERENCES public.cidades(id),
 dados jsonb NOT NULL,arquivos jsonb NOT NULL,status text NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','em_contato','concluido','arquivado')),
 consentido_em timestamptz NOT NULL DEFAULT now(),criado_em timestamptz NOT NULL DEFAULT now());
ALTER TABLE core.site_categorias ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.site_cadastros ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON core.site_categorias,core.site_cadastros FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS site_cadastros_data_idx ON core.site_cadastros(criado_em DESC);

CREATE OR REPLACE FUNCTION api.site_catalogo() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('cidades',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'cidade',cidade,'latitude',latitude,'longitude',longitude) ORDER BY cidade),'[]'::jsonb) FROM public.cidades WHERE ativo),
 'categorias',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY nome),'[]'::jsonb) FROM core.site_categorias c))
$$;
CREATE OR REPLACE FUNCTION api.site_cadastro_receber(p_id uuid,p_request_id uuid,p_hash text,p_tipo text,p_cidade uuid,p_dados jsonb,p_arquivos jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE existing core.site_cadastros;
BEGIN
 IF p_id IS NULL OR p_request_id IS NULL OR p_hash !~ '^[a-f0-9]{64}$' OR p_tipo NOT IN('motorista','negocio') OR
    NOT EXISTS(SELECT 1 FROM public.cidades WHERE id=p_cidade AND ativo) OR jsonb_typeof(p_dados)<>'object' OR jsonb_typeof(p_arquivos)<>'array' OR
    jsonb_array_length(p_arquivos) NOT BETWEEN 2 AND 4 OR coalesce(p_dados->>'telefone','') !~ '^55[0-9]{10,11}$' THEN
   RETURN jsonb_build_object('sucesso',false,'mensagem','Confira o cadastro e os documentos.');
 END IF;
 IF p_tipo='negocio' AND NOT EXISTS(SELECT 1 FROM core.site_categorias WHERE codigo=p_dados->>'tipo') THEN RETURN jsonb_build_object('sucesso',false,'mensagem','Categoria inválida.'); END IF;
 IF p_tipo='motorista' AND coalesce(p_dados->>'veiculo','') NOT IN('Moto','Carro','Bicicleta','Fiorino','Van') THEN RETURN jsonb_build_object('sucesso',false,'mensagem','Veículo inválido.'); END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_arquivos) a WHERE coalesce(a->>'path','') NOT LIKE 'cadastros-site/'||p_id::text||'/%') THEN RETURN jsonb_build_object('sucesso',false,'mensagem','Documento inválido.'); END IF;
 INSERT INTO core.site_cadastros(id,request_id,payload_hash,tipo,cidade_id,dados,arquivos) VALUES(p_id,p_request_id,p_hash,p_tipo,p_cidade,p_dados,p_arquivos) ON CONFLICT(request_id) DO NOTHING;
 SELECT * INTO existing FROM core.site_cadastros WHERE request_id=p_request_id;
 IF existing.payload_hash<>p_hash THEN RETURN jsonb_build_object('sucesso',false,'mensagem','O pedido de cadastro já foi usado com outros dados. Recarregue antes de enviar.'); END IF;
 RETURN jsonb_build_object('sucesso',true,'protocolo',existing.id,'mensagem','Cadastro recebido! Nossa equipe vai analisar os dados e falar com você pelo WhatsApp.');
END $$;

CREATE OR REPLACE FUNCTION api.painel_site_cadastros(p_sessao_token text,p_limite int DEFAULT 100) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u core.usuarios:=api._painel_op(p_sessao_token);
BEGIN
 IF u.id IS NULL OR NOT api._painel_pode(u,'cadastros') THEN RETURN api._painel_negado(); END IF;
 RETURN jsonb_build_object('sucesso',true,'itens',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.criado_em DESC),'[]'::jsonb) FROM
 (SELECT s.id,s.tipo,s.status,s.criado_em,c.cidade,s.dados,s.arquivos FROM core.site_cadastros s JOIN public.cidades c ON c.id=s.cidade_id WHERE api._painel_cidade_ok(u,c.cidade) ORDER BY s.criado_em DESC LIMIT least(greatest(p_limite,1),200)) q));
END $$;
CREATE OR REPLACE FUNCTION api.painel_site_documento(p_sessao_token text,p_id uuid,p_arquivo text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE u core.usuarios:=api._painel_op(p_sessao_token); item jsonb;
BEGIN
 IF u.id IS NULL OR NOT api._painel_pode(u,'cadastros') THEN RETURN api._painel_negado(); END IF;
 SELECT a INTO item FROM core.site_cadastros s JOIN public.cidades c ON c.id=s.cidade_id CROSS JOIN LATERAL jsonb_array_elements(s.arquivos) a
 WHERE s.id=p_id AND api._painel_cidade_ok(u,c.cidade) AND a->>'key'=p_arquivo;
 IF item IS NULL THEN RETURN jsonb_build_object('sucesso',false); END IF;
 RETURN jsonb_build_object('sucesso',true,'arquivo',item);
END $$;
REVOKE ALL ON FUNCTION api.site_catalogo(),api.site_cadastro_receber(uuid,uuid,text,text,uuid,jsonb,jsonb),api.painel_site_cadastros(text,int),api.painel_site_documento(text,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION api.site_catalogo(),api.site_cadastro_receber(uuid,uuid,text,text,uuid,jsonb,jsonb),api.painel_site_cadastros(text,int),api.painel_site_documento(text,uuid,text) TO service_role;
NOTIFY pgrst,'reload schema';
